data.query:
query ProjectMilestones($first: Int!, $after: String, $filter: ProjectMilestoneFilter, $orderBy: PaginationOrderBy) {
    projectMilestones(first: $first, after: $after, filter: $filter, orderBy: $orderBy) {
        nodes {
            id
            name
            description
            progress
            status
            targetDate
            createdAt
            updatedAt
            project {
                id
                name
            }
        }
        pageInfo {
            hasNextPage
            endCursor
        }
    }
}
